    button:focus-visible,
    .radio-card input:focus-visible {
      outline: 3px solid rgba(79, 70, 229, 0.35);
      outline-offset: 3px;
    }

    .status-text {
      min-height: 1.5rem;
      color: var(--success);
      font-weight: 600;
    }

    @media (max-width: 32rem) {
      .panel {
        padding: 1.25rem;
      }

      fieldset {
        padding: 1rem;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
