      box-shadow: 0 16px 32px rgba(79, 70, 229, 0.24);
    }

    button:hover {
      filter: brightness(1.03);
    }

    button:focus-visible,
    .radio-card input:focus-visible {
      outline: 3px solid rgba(79, 70, 229, 0.35);
      outline-offset: 3px;
    }

    .status-text {
      min-height: 1.5rem;
      color: var(--success);
      font-weight: 600;
    }

    @media (max-width: 32rem) {
      .panel {
        padding: 1.25rem;
      }

      fieldset {
        padding: 1rem;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto;
        transition: none !important;
      }
    }

    @media (forced-colors: active) {
      .panel,
      fieldset,
      .radio-card {
        border-color: CanvasText;
        background: Canvas;
        box-shadow: none;
      }

      button {
        background: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonText;
        box-shadow: none;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <main id="maincontent" tabindex="-1">
    <section class="panel" aria-labelledby="page-title">
      <p class="eyebrow">Preferences</p>
      <h1 id="page-title">Choose how you want to stay updated</h1>
      <p class="intro">
        Select one notification channel so we can send alerts in the way that works best for you.
      </p>

      <form id="notification-form" novalidate>
        <div class="form-field">
          <fieldset id="notification-group" aria-describedby="notification-help notification-error">
            <legend>
              How do you prefer to receive notifications?
              <span class="required" aria-hidden="true">*</span>
            </legend>
            <p id="notification-help" class="help-text">Choose one option before submitting the form.</p>
            <p id="notification-error" class="error-text" role="alert">Error: Select how you prefer to receive notifications.</p>

            <div class="radio-list">
              <div class="radio-card">
                <input id="notification-email" type="radio" name="notificationPreference" value="Email" required>
                <label for="notification-email">Email</label>
              </div>

              <div class="radio-card">
                <input id="notification-sms" type="radio" name="notificationPreference" value="SMS" required>
                <label for="notification-sms">SMS</label>
              </div>

              <div class="radio-card">
                <input id="notification-push" type="radio" name="notificationPreference" value="Push Notifications" required>
                <label for="notification-push">Push Notifications</label>
              </div>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Save preference</button>
          <p id="form-status" class="status-text" aria-live="polite"></p>
        </div>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById("notification-form");
    const radios = Array.from(form.elements.namedItem("notificationPreference"));
    const errorMessage = document.getElementById("notification-error");
    const statusMessage = document.getElementById("form-status");

    const setErrorState = (showError) => {
      errorMessage.dataset.visible = String(showError);
      radios.forEach((radio) => {
        radio.setAttribute("aria-invalid", String(showError));
      });
    };

    const getSelectedRadio = () => radios.find((radio) => radio.checked);

    radios.forEach((radio) => {
      radio.addEventListener("change", () => {
        setErrorState(false);
        statusMessage.textContent = "";
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const selectedRadio = getSelectedRadio();

      if (!selectedRadio) {
        setErrorState(true);
        statusMessage.textContent = "";
        radios[0].focus();
        return;
      }

      setErrorState(false);
      statusMessage.textContent = "Preference saved: " + selectedRadio.value + ".";
    });
  </script>
</body>
</html>
