   <title>Notification Preferences</title>
   <style>
     :root {
       color-scheme: light dark;
       --bg: #f3f6fb;
       --surface: rgba(255, 255, 255, 0.88);
       --surface-strong: #ffffff;
       --text: #172033;
       --muted: #5f6b85;
       --border: rgba(23, 32, 51, 0.12);
       --border-strong: rgba(58, 89, 255, 0.35);
       --accent: #4f46e5;
       --accent-strong: #3730a3;
       --focus: #1d4ed8;
       --shadow: 0 24px 60px rgba(18, 31, 53, 0.14);
       --error: #b42318;
       --success: #0f7b49;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       background:
         radial-gradient(circle at top, rgba(99, 102, 241, 0.18), transparent 32%),
         linear-gradient(180deg, #f8faff 0%, var(--bg) 100%);
       color: var(--text);
     }

     .skip-link {
       position: absolute;
       left: 1rem;
       top: 1rem;
       transform: translateY(-220%);
       padding: 0.75rem 1rem;
       border-radius: 0.75rem;
       background: var(--surface-strong);
       color: var(--text);
       box-shadow: var(--shadow);
       z-index: 10;
     }

     .skip-link:focus {
       transform: translateY(0);
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     main {
       display: grid;
       place-items: center;
       min-height: 100vh;
       padding: 2rem 1rem;
     }

     .panel {
       width: min(100%, 40rem);
       padding: clamp(1.5rem, 4vw, 2.5rem);
       border: 1px solid var(--border);
       border-radius: 1.5rem;
       background: var(--surface);
       backdrop-filter: blur(18px);
       box-shadow: var(--shadow);
     }

     .eyebrow {
       margin: 0 0 0.75rem;
       font-size: 0.875rem;
       font-weight: 700;
       letter-spacing: 0.08em;
       text-transform: uppercase;
       color: var(--accent);
     }

     h1 {
       margin: 0;
       font-size: clamp(1.875rem, 5vw, 2.5rem);
       line-height: 1.1;
     }

     .intro {
       margin: 0.875rem 0 2rem;
       max-width: 34rem;
       color: var(--muted);
       font-size: 1rem;
       line-height: 1.6;
     }

     form {
       display: grid;
       gap: 1.5rem;
     }

     .form-field {
       margin: 0;
     }

     fieldset {
       margin: 0;
       padding: 1.25rem;
       border: 1px solid var(--border);
       border-radius: 1.25rem;
       background: rgba(255, 255, 255, 0.72);
     }

     legend {
       padding: 0 0.5rem 0 0;
       font-size: 1.05rem;
       font-weight: 700;
     }

     .required {
       color: var(--accent-strong);
     }

     .help-text,
     .error-text,
     .status-text {
       margin: 0 0 1rem;
       font-size: 0.95rem;
       line-height: 1.5;
     }

     .help-text {
       color: var(--muted);
     }

     .error-text {
       display: none;
       color: var(--error);
       font-weight: 600;
     }

     .error-text[data-visible="true"] {
       display: block;
     }

     .radio-list {
       display: grid;
       gap: 0.875rem;
     }

     .radio-card {
       position: relative;
       display: flex;
       align-items: center;
       gap: 0.875rem;
       padding: 1rem 1rem 1rem 0.95rem;
       border: 1px solid var(--border);
       border-radius: 1rem;
       background: var(--surface-strong);
       transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
     }

     .radio-card:focus-within {
       border-color: var(--focus);
       box-shadow: 0 0 0 3px var(--focus);
       transform: translateY(-1px);
     }

     .radio-card input {
       width: 1.15rem;
       height: 1.15rem;
       margin: 0;
       accent-color: var(--accent);
       flex: none;
     }

     .radio-card label {
       flex: 1;
       cursor: pointer;
       font-weight: 600;
     }

     .actions {
       display: flex;
       align-items: center;
       gap: 1rem;
       flex-wrap: wrap;
     }

     button {
       border: 0;
       border-radius: 999px;
       padding: 0.95rem 1.4rem;
       background: linear-gradient(135deg, var(--accent) 0%, #7c3aed 100%);
       color: #ffffff;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       box-shadow: 0 16px 32px rgba(79, 70, 229, 0.24);
     }

     button:hover {
       filter: brightness(1.03);
     }

     button:focus-visible,
     .radio-card input:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     .status-text {
       min-height: 1.5rem;
       color: var(--success);
       font-weight: 600;
     }

     @media (max-width: 32rem) {
       .panel {
         padding: 1.25rem;
       }

       fieldset {
         padding: 1rem;
       }
     }

     @media (prefers-reduced-motion: reduce) {
       *,
       *::before,
       *::after {
         scroll-behavior: auto;
         transition: none !important;
       }
     }

     @media (forced-colors: active) {
       .panel,
       fieldset,
       .radio-card {
         border-color: CanvasText;
         background: Canvas;
         box-shadow: none;
       }

       button {
         background: ButtonFace;
         color: ButtonText;
         border: 1px solid ButtonText;
         box-shadow: none;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#maincontent">Skip to main content</a>

   <main id="maincontent" tabindex="-1">
     <section class="panel" aria-labelledby="page-title">
       <p class="eyebrow">Preferences</p>
       <h1 id="page-title">Choose how you want to stay updated</h1>
       <p class="intro">
         Select one notification channel so we can send alerts in the way that works best for you.
       </p>

       <form id="notification-form" novalidate>
         <div class="form-field">
           <fieldset id="notification-group" aria-describedby="notification-help notification-error">
             <legend>
               How do you prefer to receive notifications?
               <span class="required" aria-hidden="true">*</span>
             </legend>
             <p id="notification-help" class="help-text">Choose one option before submitting the form.</p>
             <p id="notification-error" class="error-text" role="alert">Error: Select how you prefer to receive notifications.</p>

             <div class="radio-list">
               <div class="radio-card">
                 <input id="notification-email" type="radio" name="notificationPreference" value="Email" required>
                 <label for="notification-email">Email</label>
               </div>

               <div class="radio-card">
                 <input id="notification-sms" type="radio" name="notificationPreference" value="SMS" required>
                 <label for="notification-sms">SMS</label>
               </div>

               <div class="radio-card">
                 <input id="notification-push" type="radio" name="notificationPreference" value="Push Notifications" required>
                 <label for="notification-push">Push Notifications</label>
               </div>
             </div>
           </fieldset>
         </div>

         <div class="actions">
           <button type="submit">Save preference</button>
           <p id="form-status" class="status-text" aria-live="polite"></p>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById("notification-form");
     const radios = Array.from(form.elements.namedItem("notificationPreference"));
     const errorMessage = document.getElementById("notification-error");
     const statusMessage = document.getElementById("form-status");

     const setErrorState = (showError) => {
       errorMessage.dataset.visible = String(showError);
       radios.forEach((radio) => {
         radio.setAttribute("aria-invalid", String(showError));
       });
     };

     const getSelectedRadio = () => radios.find((radio) => radio.checked);

     radios.forEach((radio) => {
       radio.addEventListener("change", () => {
         setErrorState(false);
         statusMessage.textContent = "";
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const selectedRadio = getSelectedRadio();

       if (!selectedRadio) {
         setErrorState(true);
         statusMessage.textContent = "";
         radios[0].focus();
         return;
       }

       setErrorState(false);
       statusMessage.textContent = "Preference saved: " + selectedRadio.value + ".";
     });
   </script>
 </body>
 </html>

